const ids = orders.map(o => o.orderId);

pm.test("Retrieved 3 orders", () => {
    pm.expect(orders.length).to.eql(3);
});

pm.test("All order IDs are unique", () => {
    pm.expect(new Set(ids).size).to.eql(orders.length);
});

